  "quiz.click_chips_hint": { en: "Click the word chips below in the correct order...", te: "క్రింద ఉన్న పద చిప్‌లను సరైన క్రమంలో క్లిక్ చేయండి...", hi: "नीचे दिए गए शब्द चिप्स को सही क्रम में क्लिक करें...", ta: "கீழே உள்ள சொல் சிப்புகளை சரியான வரிசையில் கிளிக் செய்யவும்...", kn: "ಕೆಳಗಿನ ಪದ ಚಿಪ್‌ಗಳನ್ನು ಸರಿಯಾದ ಕ್ರಮದಲ್ಲಿ ಕ್ಲಿಕ್ ಮಾಡಿ...", bn: "নিচের শব্দ চিপগুলো সঠিক ক্রমে ক্লিক করুন...", mr: "खालील शब्द चिप्स योग्य क्रमाने क्लिक करा..." },
  "quiz.reset": { en: "Reset", te: "రీసెట్", hi: "रीसेट", ta: "மீட்டமை", kn: "ಮರುಹೊಂದಿಸಿ", bn: "রিসেট", mr: "रीसेट" },
