  "quiz.target_label": { en: "Target:", te: "లక్ష్యం:", hi: "लक्ष्य:", ta: "இலக்கு:", kn: "ಗುರಿ:", bn: "লক্ষ্য:", mr: "लक्ष्य:" },
  "quiz.exit_quiz": { en: "Exit Quiz", te: "క్విజ్ నుండి నిష్క్రమించండి", hi: "क्विज़ से बाहर निकलें", ta: "வினாடி வினாவை விடுக", kn: "ಕ್ವಿಜ್‌ನಿಂದ ನಿರ್ಗಮಿಸಿ", bn: "কুইজ থেকে বেরিয়ে যান", mr: "प्रश्नमंजुषा सोडा" },
