  "doctor.common_mistakes_title": { en: "Common Mistakes with this Pattern", te: "ఈ నమూనాతో సాధారణ తప్పులు", hi: "इस पैटर्न के साथ सामान्य गलतियाँ", ta: "இந்த முறையில் பொதுவான தவறுகள்", kn: "ಈ ಮಾದರಿಯೊಂದಿಗೆ ಸಾಮಾನ್ಯ ತಪ್ಪುಗಳು", bn: "এই প্যাটার্নের সাধারণ ভুল", mr: "या नमुन्यातील सामान्य चुका" },
