  "dashboard.good_morning": { en: "Good morning", te: "శుభోదయం", hi: "सुप्रभात", ta: "காலை வணக்கம்", kn: "ಶುಭೋದಯ", bn: "শুভ সকাল", mr: "शुभ सकाळ" },
  "dashboard.good_afternoon": { en: "Good afternoon", te: "శుభ మధ్యాహ్నం", hi: "शुभ दोपहर", ta: "மதிய வணக்கம்", kn: "ಶುಭ ಮಧ್ಯಾಹ್ನ", bn: "শুভ অপরাহ্ন", mr: "शुभ दुपार" },
  "dashboard.good_evening": { en: "Good evening", te: "శుభ సాయంత్రం", hi: "शुभ संध्या", ta: "மாலை வணக்கம்", kn: "ಶುಭ ಸಂಜೆ", bn: "শুভ সন্ধ্যা", mr: "शुभ संध्याकाळ" },
  "dashboard.learner_fallback": { en: "Learner", te: "అభ్యాసకుడు", hi: "शिक्षार्थी", ta: "கற்பவர்", kn: "ಕಲಿಯುವವರು", bn: "শিক্ষার্থী", mr: "विद्यार्थी" },
  "dashboard.motivation_subtitle": { en: "Small steps every day lead to big progress.", te: "ప్రతిరోజూ చిన్న అడుగులు పెద్ద పురోగతికి దారితీస్తాయి.", hi: "हर दिन छोटे कदम बड़ी प्रगति की ओर ले जाते हैं।", ta: "ஒவ்வொரு நாளும் சிறு அடிகள் பெரிய முன்னேற்றத்திற்கு வழிவகுக்கும்.", kn: "ಪ್ರತಿದಿನ ಸಣ್ಣ ಹೆಜ್ಜೆಗಳು ದೊಡ್ಡ ಪ್ರಗತಿಗೆ ಕಾರಣವಾಗುತ್ತವೆ.", bn: "প্রতিদিনের ছোট পদক্ষেপ বড় অগ্রগতির দিকে নিয়ে যায়।", mr: "दररोजची छोटी पावले मोठ्या प्रगतीकडे नेतात." },
  "dashboard.day_streak": { en: "Day Streak", te: "రోజుల స్ట్రీక్", hi: "दिन स्ट्रीक", ta: "நாள் தொடர்ச்சி", kn: "ದಿನ ಸ್ಟ್ರೀಕ್", bn: "দিন স্ট্রিক", mr: "दिवस स्ट्रीक" },
  "dashboard.complete": { en: "Complete", te: "పూర్తయింది", hi: "पूर्ण", ta: "முடிந்தது", kn: "ಪೂರ್ಣಗೊಂಡಿದೆ", bn: "সম্পূর্ণ", mr: "पूर्ण" },
  "dashboard.todays_goal": { en: "Today's Goal", te: "ఈరోజు లక్ష్యం", hi: "आज का लक्ष्य", ta: "இன்றைய இலக்கு", kn: "ಇಂದಿನ ಗುರಿ", bn: "আজকের লক্ষ্য", mr: "आजचे ध्येय" },
  "dashboard.active_level_badge": { en: "Active CEFR Level", te: "క్రియాశీల CEFR స్థాయి", hi: "सक्रिय CEFR स्तर", ta: "செயலில் உள்ள CEFR நிலை", kn: "ಸಕ್ರಿಯ CEFR ಹಂತ", bn: "সক্রিয় CEFR স্তর", mr: "सक्रिय CEFR स्तर" },
  "dashboard.lms_portal": { en: "LMS Portal", te: "LMS పోర్టల్", hi: "LMS पोर्टल", ta: "LMS தளம்", kn: "LMS ಪೋರ್ಟಲ್", bn: "LMS পোর্টাল", mr: "LMS पोर्टल" },
  "dashboard.hero_title": { en: "Ready to elevate your English today?", te: "మీ ఆంగ్లాన్ని ఈరోజు మెరుగుపరచడానికి సిద్ధంగా ఉన్నారా?", hi: "क्या आप आज अपनी अंग्रेज़ी को बेहतर बनाने के लिए तैयार हैं?", ta: "இன்று உங்கள் ஆங்கிலத்தை மேம்படுத்த தயாரா?", kn: "ಇಂದು ನಿಮ್ಮ ಇಂಗ್ಲಿಷ್ ಅನ್ನು ಸುಧಾರಿಸಲು ಸಿದ್ಧರಿದ್ದೀರಾ?", bn: "আজ আপনার ইংরেজি উন্নত করতে প্রস্তুত?", mr: "आज तुमचे इंग्रजी सुधारण्यास तयार आहात का?" },
  "dashboard.hero_desc": { en: "Complete your level tutorials, build vocabulary fluency, and pass benchmark exams to unlock advanced CEFR levels.", te: "మీ స్థాయి ట్యుటోరియల్‌లను పూర్తి చేయండి, పదజాల ధారాళతను నిర్మించండి, మరియు అధునాతన CEFR స్థాయిలను అన్‌లాక్ చేయడానికి బెంచ్‌మార్క్ పరీక్షలలో ఉత్తీర్ణులు కండి.", hi: "अपने स्तर के ट्यूटोरियल पूरे करें, शब्दावली प्रवाह बनाएं, और उन्नत CEFR स्तरों को अनलॉक करने के लिए बेंचमार्क परीक्षा पास करें।", ta: "உங்கள் நிலை பயிற்சிகளை முடித்து, சொல் சரளத்தை உருவாக்கி, மேம்பட்ட CEFR நிலைகளைத் திறக்க அளவுகோள் தேர்வுகளில் தேர்ச்சி பெறுங்கள்.", kn: "ನಿಮ್ಮ ಹಂತದ ಟ್ಯುಟೋರಿಯಲ್‌ಗಳನ್ನು ಪೂರ್ಣಗೊಳಿಸಿ, ಶಬ್ದಕೋಶ ನಿರರ್ಗಳತೆ ನಿರ್ಮಿಸಿ, ಮತ್ತು ಸುಧಾರಿತ CEFR ಹಂತಗಳನ್ನು ಅನ್‌ಲಾಕ್ ಮಾಡಲು ಬೆಂಚ್‌ಮಾರ್ಕ್ ಪರೀಕ್ಷೆಗಳಲ್ಲಿ ಉತ್ತೀರ್ಣರಾಗಿ.", bn: "আপনার স্তরের টিউটোরিয়াল সম্পূর্ণ করুন, শব্দভাণ্ডার সাবলীলতা তৈরি করুন এবং উন্নত CEFR স্তর আনলক করতে বেঞ্চমার্ক পরীক্ষায় উত্তীর্ণ হন।", mr: "तुमचे स्तर ट्युटोरियल पूर्ण करा, शब्दसंग्रह अस्खलितता तयार करा व प्रगत CEFR स्तर अनलॉक करण्यासाठी बेंचमार्क परीक्षा उत्तीर्ण करा." },
