  "dashboard.active_mins": { en: "active mins", te: "క్రియాశీల నిమిషాలు", hi: "सक्रिय मिनट", ta: "செயலில் உள்ள நிமிடங்கள்", kn: "ಸಕ್ರಿಯ ನಿಮಿಷಗಳು", bn: "সক্রিয় মিনিট", mr: "सक्रिय मिनिटे" },
