  "c2.click_tier_hint": { en: "Click any tier to view focused curriculum", te: "కేంద్రీకృత పాఠ్యాంశాన్ని చూడటానికి ఏదైనా టైర్‌ను క్లిక్ చేయండి", hi: "केंद्रित पाठ्यक्रम देखने के लिए किसी भी स्तर पर क्लिक करें", ta: "கவனம் செலுத்தப்பட்ட பாடத்திட்டத்தைப் பார்க்க எந்த அடுக்கையும் கிளிக் செய்யவும்", kn: "ಕೇಂದ್ರೀಕೃತ ಪಠ್ಯಕ್ರಮ ನೋಡಲು ಯಾವುದೇ ಹಂತವನ್ನು ಕ್ಲಿಕ್ ಮಾಡಿ", bn: "কেন্দ্রীভূত পাঠ্যক্রম দেখতে যেকোনো স্তরে ক্লিক করুন", mr: "केंद्रित अभ्यासक्रम पाहण्यासाठी कोणत्याही स्तरावर क्लिक करा" },
